sec2_new = r"""\section{Related Work}\label{sec:related}

\subsection{Cluster Ensembles and Consensus Functions}
Consensus clustering aggregates diverse partitions generated by base algorithms into an integrated consensus solution~\cite{strehl2002cluster,fred2005combining,monti2003consensus}. Classical formulations construct an $N \times N$ pairwise co-association matrix $S$ where each entry $S_{ij}$ records the fraction of base clusterings in which instances $\mathbf{x}_i$ and $\mathbf{x}_j$ co-occur in the same cluster. Graph partitioning algorithms (e.g., CSPA, HGPA, MCLA~\cite{strehl2002cluster}) or spectral clustering on $S$ then derive the consensus labels. Topchy et al.~\cite{topchy2005clustering} formalized consensus as maximum-likelihood estimation over mixture models of weak partitions.

To enhance robustness against noisy base partitions, Li et al.~\cite{li2019clustering} introduced Core-Halo consensus clustering, decomposing co-association matrices into stable core components and fuzzy halos. In deep clustering architectures, Xie et al.~\cite{xie2016unsupervised} developed Deep Embedded Clustering (DEC), learning non-linear cluster representations via autoencoders with Student's $t$-distribution soft assignment refinement. However, classical consensus retains dense $O(N^2)$ storage, while deep clustering entails iterative neural pretraining that scales poorly on small-$N$ or streaming settings.

\subsection{Anchor Graphs and Bipartite Consensus}
To overcome the $O(N^2)$ memory wall of dense co-association matrices, anchor-based methods construct bipartite graphs between $N$ data instances and $L \ll N$ representative landmark points. Fern and Brodley~\cite{fern2004solving} first formulated cluster ensemble aggregation as a bipartite graph partitioning problem. Nie et al.~\cite{nie2024fast} proposed Fast Clustering with Anchor Guidance (FCAG), achieving fast spectral partitioning by constructing anchor-to-sample graphs that bypass full similarity matrix construction. Huang et al.~\cite{huang2023fast} developed Fast Multi-View Clustering via Ensembles (FastMVC), employing random anchor sub-ensembles to achieve linear time complexity across diverse views. Huang et al.~\cite{huang2020ultra} established ultra-scalable ensemble clustering by generating anchor graphs through bipartite bipartite transfer cuts. ICC-v2 builds upon these bipartite foundations, coupling bipartite compression with linear-time feature gating to resolve high-dimensional noise.

\subsection{High-Dimensional Feature Gating and Subspace Clustering}
In high-dimensional regimes ($D \gg N$), distance concentration causes pairwise Euclidean distances to become uniformly equidistant~\cite{beyer1999nearest}, degrading distance-based consensus graphs. Random subspace ensembles (Fern and Brodley~\cite{fern2003random}) sample random subsets of features to create diversity; however, under extreme distractor noise, unguided random projections sample predominantly non-informative dimensions, causing base clusterers to collapse onto noise partitions.

Witten and Tibshirani~\cite{witten2010framework} addressed high-dimensional clustering via Sparse K-Means, introducing an $L_1$ penalty on feature weights to screen uninformative dimensions. However, iterative sparse feature weighting incurs significant computational overhead and assumes convex cluster geometry. To address this, ICC-v2 introduces linear-time Bimodality-Gated Subspace Selection (BGSS), filtering uninformative features in strictly $O(N \cdot D)$ time prior to base clusterer generation using Sarle's bimodality coefficient~\cite{sarle1983sas,ellison1987bimodality}.

\subsection{Inductive Out-of-Sample Extensions}
A fundamental limitation of classical spectral and consensus clustering is their transductive nature: partition assignments are defined exclusively for the training instances $X_{\text{train}}$. Assigning incoming test observations $\mathbf{x}^*$ traditionally requires re-solving the consensus problem over $N + |\mathcal{X}_{\text{test}}|$ instances.

Bengio et al.~\cite{bengio2004out} formulated out-of-sample extensions for spectral graph partitioning using the Nystr\"om kernel approximation, and Breiman's Random Forest~\cite{breiman2001random} provides supervised out-of-sample propagation when trained on cluster pseudo-labels. In ICC-v2, out-of-sample projection is performed in closed-form $O(K \cdot |\mathcal{F}_{\text{active}}|)$ time via stability-weighted active subspace centroids, providing rapid query evaluation without graph reconstruction.

Table~\ref{tab:taxonomy_comparison} summarizes the methodological taxonomy comparing ICC-v2 against the consensus frameworks evaluated in our benchmarks.

\begin{table*}[!t]
\caption{Methodological Taxonomy and Comparison Across Evaluated Consensus Paradigms}
\label{tab:taxonomy_comparison}
\centering
\resizebox{\textwidth}{!}{%
\begin{tabular}{@{}lccccc@{}}
\toprule
\textbf{Method} & \textbf{Feature Gating} & \textbf{Core Filtering} & \textbf{Inductive} & \textbf{Aux. Mem.} & \textbf{High-$D$ Noise} \\
\midrule
Standard Consensus~\cite{fred2005combining} & None           & None         & No          & $O(N^2)$ & Susceptible \\
Core-Halo Consensus~\cite{li2019clustering} & None           & Determinacy  & No          & $O(N^2)$ & Susceptible \\
FCAG~\cite{nie2024fast}                     & None           & K-Means Anchors & No       & $O(NL)$  & Susceptible \\
FastMVC~\cite{huang2023fast}                & None           & K-Means Anchors & No       & $O(NL)$  & Susceptible \\
DEC~\cite{xie2016unsupervised}              & Latent AE      & None         & Neural Net  & $O(N \cdot d)$ & Moderate \\
Sparse K-Means~\cite{witten2010framework}   & $L_1$ Penalty  & None         & Centroid    & $O(N \cdot D)$ & Filtered \\
ICC-v1 (Legacy)~\cite{fern2003random}       & Ambient Random & None         & No          & $O(N^2)$ & Susceptible \\
\textbf{ICC-v2 (Ours)}                      & \textbf{BGSS}  & \textbf{Core Anchors} & \textbf{Centroid} & $\mathbf{O(NL)}$ & \textbf{Gated Subspace} \\
\bottomrule
\end{tabular}%
}
\end{table*}"""

